window.blogDetail = {"blogId":1506153242,"blogType":0,"pubTime":"2017-09-23 15:54","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"我读红楼梦（二十三）第19回 情切切良宵花解语，意绵绵静日玉生香——贾府中的奴仆阶级","commentNum":0,"effect1":1024,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"经过了第18回中元妃省亲的一段高潮之后呢，故事的情节又趋于平淡。作者在开头用两三行文字收束上回，紧接着，在这一回以及接下来的第二十回中，作者通过对贾府中非上层人物的刻画，把笔墨渐渐的从主角上移开，为我们展示了贾府各个阶层的生活情状，从而体现了贾府中森严的等级制度和那些微不足道的小人物心中的爱怨憎恨，以及他们在夹缝中不断苦苦挣扎，为求生存的矛盾心理。这一回中，作者描写的是家族中不同的奴仆阶级表现出来...","artype":1,"arUins":"","blogid":1506153242,"voteids":0,"pubtime":1506153242,"replynum":0,"category":"个人日记","effect":1024,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1506153242,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"我读红楼梦（二十三）第19回 情切切良宵花解语，意绵绵静日玉生香——贾府中的奴仆阶级","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1506153242"}